style.css:
@-moz-document domain("google.com") {
/* 1. Main Background Image */
    body, #main, .main {
        background-image: url("https://imgur.com") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        color: #ffffff !important;
    }

    /* 2. Transparent Containers (Removes solid white blocks over your image) */
    #cnt, #rcnt, .center_col, .g, .MjjYud, .jtfY8b {
        background: transparent !important;
    }

    /* 3. The Search Bar */
    .gLFyf, .RNNXgb {
        background-color: rgba(255, 255, 255, 0.15) !important;
        backdrop-filter: blur(10px) !important;
        -webkit-backdrop-filter: blur(10px) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        color: #ffffff !important;
        border-radius: 24px !important;
    }

    /* 4. Search Results Headers & Links */
    h3, .LC20lb, a:link {
        color: #4ac3ff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }
    
    /* 5. Visited Links */
    a:visited {
        color: #d186ff !important;
    }

    /* 6. Snippet Text (Descriptions below links) */
    .VwiC3b, .st, span, .w7w7ce {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }
}
